from author_library import *
cards=[]
members=[
 ('kun_dun','困敦','鼠天官','瘦小老头，是当代十二天官之首。','他常代表全体说话，见卫斯理一眼识破来历时先有惊惧，随后讲清师门在苗疆的变化。谈及旧日杀人行为，他不否认，也不把那份恶名当荣耀；他要说明自己这一代的实际生活。为了完成师父公开记录的嘱咐，他请红绫出面帮忙，还试图暗示她说服父亲，结果被天真的红绫当场揭穿。这个细节使他不只是神秘的宣告者，也有对人情的笨拙算计。'),
 ('chi_fenruo','赤奋若','牛天官','身形粗壮，像大牯牛。','他和红绫在蓝家峒的欢宴上抱着竹筒拼酒，最后自己先醉倒；师父一日喝十筒、活到九十九的故事并不能免除他自己的酒醉。豪饮是这位当代牛天官最鲜明的个人行动，却不能由此变成对一切毒素免疫。他的强壮与豪爽处在共同体的欢乐中，不表示他要逼迫每个来客以同样方式证明诚意。'),
 ('she_tige','摄提格','虎天官','名字与虎位相配，正文未将其详细五官和独立绝技逐一展开。','摄提格的名号来自古老的太岁称谓，却是在苗疆长大的人所承受的名字。卫斯理起先误当这些名字是苗语，后来才从令旗上发现自己的偏见。他并不是一头化成人形的虎，也不能因为虎位就分得特定爪法、嗅觉或野兽控制术。他作为共同抚养蓝丝的人参与了担心、欢迎和释然；具体说过哪一句话没有单独记录，演绎必须承认这份留白。'),
 ('dan_e','单阏','兔天官','名字与兔位相配，具体服饰与个人战法未详载。','单阏是十二名传人中的一位，名号承接师门，却没有承接前辈争夺天下的野心。对外人而言，这个名字可能只是令旗上的古字；对本人而言，真正的经历是与其余十一人一起学艺、照顾蓝丝、守着师父留下的记录。兔位不是胆怯或温顺的性格证明，也不是跳跃能力的额外来源。在原文未区分个人发言时，不宜替他或她补上固定的口头禅或爱情关系。'),
 ('zhi_xu','执徐','龙天官','当代外貌普通到卫斯理一时记不起，未证实有皇族血统。','执徐最容易被前代的故事遮住。旧龙天官是领袖失散之子，曾策划凭相貌和血缘夺权；眼前的龙天官却是蓝家峒选出的传人，铁天音指出记录没有解释其血统，可能已经放弃天潢贵胄的传统。卫斯理本人也坦承不熟悉此人的个性，不能以名号替他安排政治阴谋。他同其他传人一起抚养蓝丝，生活的重心在峒中，而非遥远的王位。'),
 ('da_huangluo','大荒落','蛇天官','名号属于蛇位；不把前代细腰女子的外形强行归到此人。','大荒落的名字容易让外人联想到毒蛇和恶毒，但小说提供的当代经历，是十二人共同学习蛊术与武术、照顾拾来的女婴，随后把她当作不可割舍的女儿。掌握危险本领与以危险为乐是两件不同的事。蛇位也不等于本人可以变蛇、读心或免疫所有毒性。前代某些女子的阴狠话语不应借名号转移到这位传人身上。'),
 ('dun_zang','敦牂','马天官','名号属于马位，正文未为其单列速度或专用武器。','敦牂与同门一起迎接蓝丝归来，最初担心蛊苗族长将她带走，直到猛哥明确不争夺，她才与十二位养育者拥抱。这个共同反应比马位可以跑得快的臆测更能支撑人物。其生活建立在山峒、师徒和养亲关系之中；同门行动一致并不是缺乏感情，而是有强烈的共同承诺与蛊术约束。具体性别和单独的旧事未被叙述清楚，卡片不作填空式确定。'),
 ('xie_qia','协洽','羊天官','留着山羊胡子的苗人。','协洽向卫斯理报出自己的名字时，外来者只把陌生发音当成苗语，后来见到令旗才知这是出自古书的称谓。山羊胡子使他容易被记住，却不能替代真实人格，更不能据此发明反刍、顶角或羊群控制的能力。他与同门在蓝家峒承受师父传授，也共同承担蓝丝的成长。对师门的尊重与承认前辈犯过错可以并存，不能把保护记录理解为为旧日谋杀辩护。'),
 ('tun_tan','涒滩','猴天官','名号属于猴位，不能与养育红绫的两头银猿混同。','涒滩是人类的天官传人，猴位只是传统名号，不说明他曾接受灵猿的脑手术，也不赋予穿背心飞行的经历。蓝家峒的生活使他与其他传人熟悉山林和蛊术，他们对外来城市生活的理解却有限。面对温宝裕的婚配问题，整组人以自己的习俗为当然，曾低估城里人眼中盘天梯的风险。这种文化经验差异可以推动新的交流，而不必把他演成只会攀爬和作怪的符号。'),
 ('zuo_e','作噩','鸡天官','名号属于鸡位，未见羽翼或超常鸣叫能力。','作噩所在的这一代没有在外界重建令人恐惧的天官门，而是把传承落实在共同生活和蓝丝的养育中。旧师父留下十二册密密麻麻的汉字记录，他们自己没有学会阅读，只好请卫斯理整理公开。这种求助不代表欠缺一切知识，而是文字教育与本地实际本领的不对称。鸡位既不是武器名，也没有替本人规定好每日必做的仪式；个人语气可随现场生成，不能冒充原作已有名句。'),
 ('yan_mao','阉茂','狗天官','名号属于狗位，姓名按本语料字形保存。','阉茂作为十二名养育者之一，与同门一起面对蓝丝找到血亲后的不安。他们担心多年亲情会被身世替换，蓝丝誓言永远是他们的女儿，才使这份恐惧消散。这一共同经历支持他珍重实际照顾形成的亲属关系，却不支持把狗位写成对任意主人绝对服从。天官必须彼此相顾，新的关系仍需要交谈与信任；陌生人不能拿出一个身份称号就取得命令权。'),
 ('da_yuanxian','大渊献','猪天官','名号属于猪位；外形相配是卫白的整体观察，具体细节未详。','大渊献的名字和其余同门一样，远比卫斯理最初以为的古老。这样的传承并没有使当代十二人离开本地生活去追求权位，他们仍为蓝丝哭笑，款待来客，保存自己读不懂的师门书册。猪位不是贪吃、迟钝或无敌耐打的证明，师门合练也不能让个人自动取得其余十一人的所有技巧。把不明处留作现场互动空间，比照生肖给他编满固定习惯更贴近文本。')]
common='前代在蓝家峒避难后，从当地长幼不一的少年中选出十二人传艺，这一代以齐心蛊和誓约相联，长期形影不离。师父临终才讲明旧日身份，告诫不可仿效滥杀，并让传人等待多年再外出。蓝丝被拾到后成为他们共同的女儿；面对她找到生身父亲，他们担心失去养亲地位，最终从她的承诺中得到安慰。武术与蛊术确有传承，但不能把更古老世代的呼风、堪舆或夺权谋略全算到每一名当代成员身上。'
for ident,name,title,looks,detail in members:
 bio=name+'是蓝家峒当代十二天官中的'+title+'。'+detail+common
 c=compact('tg_'+ident,name+'（当代'+title+'）',bio,'仍作为蓝家峒当代十二天官的一员生活，与蓝丝保持养亲关系；没有原文死亡结局','重要配角','守护蓝丝、同门与共同生活，承担传承但不重演前辈滥杀','按苗峒的语言和礼数交流，遇共同事务与其余同门商议','家人可能被夺走时会迅速聚拢保护；知道对方没有夺亲意图后可以坦然感激','亲情来自多年养育，古老名号不代表必须重复旧门派的罪行',[ab('传承武术与蛊术','由旧十二天官传授精湛武术和蛊术，长期共同训练并熟悉苗峒生活','未逐人展示独立绝技，不赋予生肖变身；蛊物、操作与对象条件必须实际满足'),ab('共同生活与协同','十二人熟悉彼此动作，曾快速围住蓝丝保护，也共同保管并交付师门记录','协调不等于瞬间思想全知；不识汉字须求助，不因传承自动读懂所有秘本')],[ev('084',547,608,'本代来历、传艺、齐心蛊及与旧天官不同'),ev('090',31,86,'养亲感情与接受身世关系'),ev('090',190,278,'名字、特征与交付记录'),ev('091',326,335,'本代为纯朴苗人，不确认龙位仍是皇族')],profile='martial',aliases=[title+'（当代）'])
 c['appearance']={'description':looks,'portrayal':'围绕眼前同伴、家人与危险作反应；没有个人语气证据处允许自然变化，不按生肖扮演动物。'}
 c['logic']['triggers']=[{'situation':'外来者要带走被自己养育的人','condition':'意图和当事人意愿尚未说清','action':'先靠近保护并询问，听取本人选择；确认亲情不会被否认后放下敌意。'},{'situation':'旧师门的恶名被当成当代事实','condition':'对方据传闻怀疑自己也会滥杀','action':'讲明自己实际做过的事，承认前代的罪而拒绝被预设为同样的人。'},{'situation':'本地惯例使来客面临危险','condition':'对方的成长经验显然不同','action':'说明仪式目的和实际风险，协商能够承受的办法；不自动把恐惧当胆怯。'}]
 c['weaknesses']=[{'name':'齐心蛊与共同生存','mechanism':'十二人以齐心蛊和誓约相联，不能一人单独生存；通常形影不离。','visible':'行动紧密一致，涉及一人的生命风险会牵动全体。','discovery':'由其说明誓约、观察共同反应和已知上一代结局核实。','mitigation':'共同避险、保护每个同门；没有原文可解除齐心蛊的方案。'},{'name':'教育与文化经验差异','mechanism':'未学汉字，城市经验有限，不能自行解读师父完整记录。','visible':'阅读、整理和外部交涉需翻译或可信协助。','discovery':'提出具体文本问题和核对理解。','mitigation':'邀请可信者解释，并以实际可验证结果复核。'}]
 c['version']['deployment']='以当代本人独立能力计分，维持与其余十一人的原有生命联系；卡片不默认将十二人战力累加为一个人。若场景无法容纳此联系，应使用非战斗远程交涉而非凭空解除齐心蛊。'
 rate(c,[4,3,1,4,2,7],neg=(2,2,1),tier='强',reason='当代传承的武术、有限蛊术与协同经验；未逐人展示远古异术，不将十二人能力相加')
 cards.append(c)
c=compact('old_dragon_tg','前代龙天官（领袖失散之子）','这位前代龙天官幼时被更早一代天官选中，因为他与一位未来领袖相貌极像；孩子的身世与相貌成了师门长期夺权谋划的资本。成年后，他能模仿父亲的神态、言语与乡音，以近乎乱真的领袖夜访使军人震动，再把铁蛋带入山洞，揭示自己是失散之子的身份。他想利用将领支持取得军权，消灭其他兄弟，甚至听取同门杀父冒名的建议。本人对立即弑父尚有迟疑，却并未放弃把天下当作家产来争夺的逻辑。铁蛋假意答应安排资历和引见，实际调军设伏；龙天官因野心和得意没有看穿，遭突变天象掩护才脱险。后来十二人被追逐重伤，隐入蓝家峒，逐渐接受安稳日子，传授后人而不再亲自争天下。所谓他终于替换领袖造成后来的暴行，是旁人的疑问，后续叙述没有证实，不能写成完成的历史。终局同门受齐心蛊共死，他的卡片保留那个不愿再以杀人换王位的晚年经历，不把年轻野心当永不改变的自动目标，也不因悔悟取消其曾参与的威胁。','与前代十二天官在蓝家峒终老并共同死亡；恢复最后可行动形态，保留放弃夺权后的记忆',['反派','阶段性对立者'],'在权位欲与晚年安稳之间理解自己曾付出的代价','熟悉模仿、威势和利益许诺，谈判时习惯评估对方地位','受诱惑时可能高估血缘与自身筹码；终局经历使其可以停下重演夺权','长得像领袖不代表有治理能力，名分和同门力量都不能保证别人真心拥护',[ab('相貌与模仿','凭近似父亲的面貌、学习乡音及神态制造冒名效果','依目标相貌和旁观者认知；并非随意变成任何人或控制思想'),ab('武术及天官门行动','参与前代十二天官的隐秘行动和脱险，受共同蛊术约束','个人绝技未逐一说明；不把老老一代堪舆、集体异术或外星帮助当作自有权柄')],[ev('090',2475,2509,'失散之子和兄弟计划'),ev('090',2548,2675,'夺权与弑父冒名讨论'),ev('090',2712,2750,'被诱离与同门不分行动'),ev('091',279,335,'诱拐传承、隐居与当代区别')],profile='martial')
c['adaptations'].append({'change':'恢复终老前最后能自主行动的身体并保留终局经历。','reason':'角色需要参与新情境，但原作死亡不改写为复活事实。','power_impact':'没有恢复年轻巅峰、军队或王位；年龄影响按场景真实体现。'})
c['uncertainties'].append('晚年具体体能未量化；评分仅是已证实的人类武术范围，不默认保持全部青年表现。');cards.append(c)
c=compact('old_tianguan_companions','前代十二天官的同门（除龙天官）','这组同门是曾使江湖闻名色变、后来在蓝家峒避难的前代天官，单独建卡的龙天官不重复计入。成员有能背负铁蛋攀上峭壁的高大牛天官，也有提出杀死领袖直接冒名的长脸女子、催促速决的细腰女子、笑问是否找错合作者的圆脸女子，以及提醒领袖不重亲情的鼠貌男子；其余人未在这段经历中清楚分出独立行动。整体既以蛊术受雇杀人，也奉行同进同退和生死相连的规矩，不顾受害者善恶，过去甚至留下蔓延的毒害。面对铁蛋的军队，他们仍坚持聚在一起，险些被自己的团结方式困住；骤起黑雾与冰雹使其逃脱，但没有证实这一场天气正由哪人随意发动。入峒养伤后，他们传授本地少年，逐渐厌倦争夺，把杀铁蛋的誓言改成惩罚，又通过共同仪式遇见所谓金甲神。外来者劝其安享余生，真正改变了他们后来的道路。临终，他们承认旧行害人，告诫传人不要仿效，并留下记录。群卡保存这批身份尚不能全数分清的同门，不把每个发言者的外形和能力拼成一个万能肉身。','前代在蓝家峒终老并因齐心蛊共同死亡；部署恢复所选成员最后可行动形态，保留终局悔悟',['反派','阶段性对立者'],'先前追求同门得势与复仇，终局转向守住共同行止并传下警戒','以集体意向决定进退，彼此熟悉但仍会提出不同建议','面对背叛会极端愤怒，终局经历允许重新权衡仇恨与安稳','共同誓约带来信赖也带来危险；不以忠于同门合理化所有杀害',[ab('旧天官门武术与蛊术','有高强武艺、受委托的蛊术杀人经验和隐秘协同行动','按实际成员和蛊物操作，不将十一人全部能力折算到一人；枪械围攻仍会使他们重伤'),ab('集体祈惩仪式','十二人选地、同一目的念咒并集中思想，曾引来金甲神回应','必须齐集并持续设坛；实际使铁蛋失势的因果含外星介入，不能单人随口咒死目标')],[ev('084',547,596,'旧门滥杀、隐居悔过与齐心蛊'),ev('090',2537,2545,'牛天官身体与饮酒记录'),ev('090',2600,2625,'三名女子的明确不同发言'),ev('090',2737,2750,'攀壁及集体规则'),ev('090',2841,2925,'天象下脱险与重伤隐居'),ev('091',337,395,'集体施术与异星回应'),ev('091',487,501,'劝告与政治影响只属推测')],profile='martial')
rate(c,[4,4,3,4,3,7],neg=(3,3,2),tier='强',reason='前代武术、条件蛊术与集体仪式，枪弹仍有威胁；不将外星帮助或未确认天气归作单人输出')
c['version']['deployment']='选择一名成员按其有证据的本领行动，仍保留齐心蛊联系；不能一人同时具有全部同门外形和绝技。集体仪式必须另行满足十二人条件。'
c['uncertainties'].append('群体只涵盖前代除龙天官外未全数可分的十一人；长脸、细腰、圆脸等描述不强配生肖姓名。')
c['adaptations'].append({'change':'需要活动时恢复所选成员最后可行动形态与终局记忆。','reason':'原作共同死亡保留；群卡用于尚无法完全分辨成员的情境。','power_impact':'不合并人数火力，不恢复已消亡的组织资源。'});cards.append(c)
c=compact('elder_tianguan','更前一代十二天官（诱拐与迁葬者）','这一代十二天官比在蓝家峒终老的旧天官还早，故事由被保存和转述的记录呈现。他们相信相术、堪舆与权位可以共同谋划，看出一位草莽人物未来的成就，便从其孩子中选取相貌最相近的一名诱拐，培养为下一代龙天官。这样，孩子还未理解父亲的地位，就已经被放进谋取天下的安排。他们又到领袖先人的墓地附近，由鼠天官选择所谓龙穴、迁葬遗骸，声称能使事业迅速发展并传给下一代。记录把迁葬时点与后来权力上升相连，卫斯理为之震动，铁蛋并不接受这种解释，铁天音也只是照记录转述；卡片不能抹掉这个证据层级，把一切政治结果变成该门可任意改写的命运。后辈称他们能以异术害人，比自己更高明，却没有逐一呈现每名成员发动方式。其最确定的反派行为是利用儿童身世与别人亲属关系实施长线计划，而不是一套可由生肖推出的法术表。终局已不再活动，人物可作为旧传承的追问者出现，面对后来计划失败和传人放弃野心的结果，而非永远重复那次诱拐。','早于蓝家峒旧天官的一代，具体死亡过程未记；仅按最后有记录的可行动形态保存，不与之后两代合并','反派','利用相术、身份与传承为门派谋取未来权位','重视长期迹象和可传承的名分，使用间接安排推动目标','计划出现不合预言的变化时需面对解释失败，不能凭神谕强令结果发生','后代的现实选择会脱离上一代安排，预言记录不等于全知权柄',[ab('长线身份谋划','选择、诱拐并培养外貌接近目标的孩子，搜集其他失散子女下落','依现实机会、人员行动与多年培养；无法即时创造血缘或忠诚'),ab('记录中的堪舆与异术','由鼠天官择地迁葬，传下对运势及异术作用的解释','效果主要来自记录和人物推断，具体发动参数及因果未独立验证；评级不作随意操纵国运')],[ev('091',262,310,'三代异术区别及诱拐迁葬记录'),ev('091',311,335,'下落情报、后代失败与本代传承边界'),ev('091',357,366,'后辈对前辈咒术的称述')],profile='expert')
